PRAGMA foreign_keys=ON;
CREATE TABLE orders(id TEXT PRIMARY KEY, claim_hash TEXT NOT NULL UNIQUE, created_at INTEGER NOT NULL, session_id TEXT UNIQUE);
CREATE TABLE checkout_attempts(order_id TEXT PRIMARY KEY REFERENCES orders(id), return_lang TEXT NOT NULL CHECK(return_lang IN ('de','en','')));
CREATE TABLE checkout_authorizations(order_id TEXT PRIMARY KEY REFERENCES orders(id), token_hash TEXT NOT NULL UNIQUE, snapshot_digest TEXT NOT NULL, expires_at INTEGER NOT NULL, used_at INTEGER);
CREATE TABLE contract_documents(language TEXT NOT NULL CHECK(language IN ('de','en')), version TEXT NOT NULL, text TEXT NOT NULL, PRIMARY KEY(language,version));
CREATE TRIGGER contract_documents_no_replace BEFORE INSERT ON contract_documents WHEN EXISTS(SELECT 1 FROM contract_documents WHERE language=NEW.language AND version=NEW.version) BEGIN SELECT RAISE(ABORT,'contract versions are immutable'); END;
CREATE TRIGGER contract_documents_no_update BEFORE UPDATE ON contract_documents BEGIN SELECT RAISE(ABORT,'contract versions are immutable'); END;
CREATE TRIGGER contract_documents_no_delete BEFORE DELETE ON contract_documents BEGIN SELECT RAISE(ABORT,'contract versions are immutable'); END;
CREATE TABLE contract_acceptances(order_id TEXT PRIMARY KEY REFERENCES orders(id), language TEXT NOT NULL CHECK(language IN ('de','en')), version TEXT NOT NULL, text TEXT NOT NULL, digest TEXT NOT NULL, accepted_at INTEGER NOT NULL);
CREATE TRIGGER contract_acceptances_no_replace BEFORE INSERT ON contract_acceptances WHEN EXISTS(SELECT 1 FROM contract_acceptances WHERE order_id=NEW.order_id) BEGIN SELECT RAISE(ABORT,'contract acceptances are immutable'); END;
CREATE TRIGGER contract_acceptances_no_update BEFORE UPDATE ON contract_acceptances BEGIN SELECT RAISE(ABORT,'contract acceptances are immutable'); END;
CREATE TRIGGER contract_acceptances_no_delete BEFORE DELETE ON contract_acceptances BEGIN SELECT RAISE(ABORT,'contract acceptances are immutable'); END;
CREATE TABLE contract_declarations(order_id TEXT NOT NULL REFERENCES orders(id), kind TEXT NOT NULL CHECK(kind IN ('early_start','withdrawal_ack')), language TEXT NOT NULL CHECK(language IN ('de','en')), version TEXT NOT NULL, text TEXT NOT NULL, digest TEXT NOT NULL, accepted_at INTEGER NOT NULL, PRIMARY KEY(order_id,kind));
CREATE TRIGGER contract_declarations_no_replace BEFORE INSERT ON contract_declarations WHEN EXISTS(SELECT 1 FROM contract_declarations WHERE order_id=NEW.order_id AND kind=NEW.kind) BEGIN SELECT RAISE(ABORT,'contract declarations are immutable'); END;
CREATE TRIGGER contract_declarations_no_update BEFORE UPDATE ON contract_declarations BEGIN SELECT RAISE(ABORT,'contract declarations are immutable'); END;
CREATE TRIGGER contract_declarations_no_delete BEFORE DELETE ON contract_declarations BEGIN SELECT RAISE(ABORT,'contract declarations are immutable'); END;
CREATE TABLE confirmation_obligations(order_id TEXT PRIMARY KEY REFERENCES orders(id), created_at INTEGER NOT NULL);
CREATE TRIGGER confirmation_obligations_no_replace BEFORE INSERT ON confirmation_obligations WHEN EXISTS(SELECT 1 FROM confirmation_obligations WHERE order_id=NEW.order_id) BEGIN SELECT RAISE(ABORT,'confirmation obligations are immutable'); END;
CREATE TRIGGER confirmation_obligations_no_update BEFORE UPDATE ON confirmation_obligations BEGIN SELECT RAISE(ABORT,'confirmation obligations are immutable'); END;
CREATE TRIGGER confirmation_obligations_no_delete BEFORE DELETE ON confirmation_obligations BEGIN SELECT RAISE(ABORT,'confirmation obligations are immutable'); END;
CREATE TABLE confirmation_jobs(order_id TEXT PRIMARY KEY REFERENCES confirmation_obligations(order_id), created_at INTEGER NOT NULL);
CREATE TABLE entitlements(id TEXT PRIMARY KEY, order_id TEXT NOT NULL UNIQUE REFERENCES orders(id), session_id TEXT NOT NULL UNIQUE, payment_intent TEXT UNIQUE, revoked INTEGER NOT NULL DEFAULT 0 CHECK(revoked IN(0,1)));
CREATE TABLE devices(license_id TEXT NOT NULL REFERENCES entitlements(id), device_id TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1 CHECK(active IN(0,1)), PRIMARY KEY(license_id,device_id));
CREATE TABLE events(id TEXT PRIMARY KEY, kind TEXT NOT NULL);
CREATE TABLE revoked_payments(payment_intent TEXT PRIMARY KEY);
CREATE TABLE rate_limits(bucket TEXT PRIMARY KEY, hits INTEGER NOT NULL, expires_at INTEGER NOT NULL);
CREATE INDEX rate_limits_expiry ON rate_limits(expires_at);
